package app.loki.anithere.dialogs

import androidx.compose.runtime.Composable
import kotlinx.serialization.json.JsonObject

// Generated by egui2compose: the dialogs translated from the desktop front end, for the app to
// open from wherever each belongs (a group's launcher, a menu entry, an engine request).

/**
 * [command] set: the menu opens that command's form (built from the engine's params doc) instead of [show].
 * [hidden]: the desktop dialog has no command to run, so the menu leaves it out; [show] is kept for when one is bound
 * (name it in dialog-commands.json and regenerate).
 */
class TranslatedDialog(val title: String, val source: String, val command: String? = null, val hidden: Boolean = false, val show: @Composable (onRun: (String, JsonObject) -> Unit, onDismiss: () -> Unit) -> Unit)

val TRANSLATED_DIALOGS: List<TranslatedDialog> = listOf(
    TranslatedDialog("Preferences", "dialogs.rs", hidden = true) { onRun, onDismiss -> PreferencesDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog guides window", "aids_dialog.rs", command = "view.guides_set") { onRun, onDismiss -> AidsDialogGuidesWindowDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog grid window", "aids_dialog.rs", command = "view.grid_set") { onRun, onDismiss -> AidsDialogGridWindowDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog spacing field", "aids_dialog.rs", hidden = true) { onRun, onDismiss -> AidsDialogSpacingFieldDialog(onRun, onDismiss) },
    TranslatedDialog("Confirm modal", "dialogs.rs", hidden = true) { onRun, onDismiss -> ConfirmModalDialog(onRun, onDismiss) },
    TranslatedDialog("Palette", "dialogs.rs", hidden = true) { onRun, onDismiss -> PaletteDialog(onRun, onDismiss) },
    TranslatedDialog("Font picker", "dialogs.rs", hidden = true) { onRun, onDismiss -> FontPickerDialog(onRun, onDismiss) },
    TranslatedDialog("Shortcut sheet", "dialogs.rs", hidden = true) { onRun, onDismiss -> ShortcutSheetDialog(onRun, onDismiss) },
)
